vec4 get_vec4(in int index) {
	int width = int( textureSize( dataArrayTex, 0 ).x );
    ivec2 texCoord = ivec2(index%width,index/width);
    vec4 col = texelFetch(dataArrayTex, texCoord, 0);
    return col;
