vec3 SampleSphere(float u1, float u2) {
    float z = 1.0 - 2.0 * u1;
    float r = sqrt(max(0.0, 1.0 - z * z));
    float phi = TWO_PI * u2;
    return vec3(r * cos(phi), r * sin(phi), z);
}

