#define BVH_DATA_

vec4 get_vec4(in int index) {
	int width = int( textureSize( iChannel0, 0 ).x );
    ivec2 texCoord = ivec2(index%width,index/width);
    vec4 col = texelFetch(iChannel0, texCoord, 0);
    return col;
}

vec4 texelFetch(int offset, ivec2 index, int pos) {
    return get_vec4(offset + index.x);
}
vec4 texelFetch(int offset, int index) {
    return get_vec4(offset + index);
}
ivec4 texelFetchI(int offset, int index) {
    return ivec4(get_vec4(offset + index));
}

makeStrI(debugInt) _num_ _endNum
makeStrF(debugFloat) _num_ _endNum

void displayData(out vec4 fragColor, vec3 resolution, vec2 fragCoord) {
    vec2 uv = fragCoord/resolution.xy;
    uv.y -= .9;                   // Start writing from top
    uv = uv * 1.6 - vec2(-.09, -.12); // Font size + padding left

    float offsetY = -0.15;
    float offsetX = -0.15;

    vec3 col = vec3(0.);

#ifdef BVH_DATA

    for (int i = 0; i < 16; i++) {
        offsetY += 0.05;
        col += debugInt(uv + vec2(-0.1 + offsetX*0.,offsetY), i);

        vec4 data1 = texelFetch(BVH, i * 3 + 0);
        col += debugFloat(uv + vec2(-0.2 + offsetX*0.,offsetY), data1.x, 1);
        col += debugFloat(uv + vec2(-0.2 + offsetX*1.,offsetY), data1.y, 1);
        col += debugFloat(uv + vec2(-0.2 + offsetX*2.,offsetY), data1.z, 1);
        vec4 data2 = texelFetch(BVH, i * 3 + 1);
        col += debugFloat(uv + vec2(-0.2 + offsetX*3.,offsetY), data2.x, 1);
        col += debugFloat(uv + vec2(-0.2 + offsetX*4.,offsetY), data2.y, 1);
        col += debugFloat(uv + vec2(-0.2 + offsetX*5.,offsetY), data2.z, 1);
        vec4 data3 = texelFetch(BVH, i * 3 + 2);
        col += debugFloat(uv + vec2(-0.2 + offsetX*6.,offsetY), data3.x, 1);
        col += debugFloat(uv + vec2(-0.2 + offsetX*7.,offsetY), data3.y, 1);
        col += debugFloat(uv + vec2(-0.2 + offsetX*8.,offsetY), data3.z, 1);

    }

#else

    int width = int(iChannelResolution[0].x);
    int height = int(iChannelResolution[0].y);
    int depth = int(iChannelResolution[0].z);

	width = int( textureSize( iChannel0, 0 ).x );
    height = int( textureSize( iChannel0, 0 ).y );
    offsetY += 0.05;
    col += debugInt(uv + vec2(-0.1 + offsetX*0.,offsetY), width);
    col += debugInt(uv + vec2(-0.1 + offsetX*1.,offsetY), height);
    col += debugInt(uv + vec2(-0.1 + offsetX*2.,offsetY), depth);

    width = int(iChannelResolution[3].x);
    height = int(iChannelResolution[3].y);
    depth = int(iChannelResolution[3].z);
    offsetY += 0.05;
    col += debugInt(uv + vec2(-0.1 + offsetX*0.,offsetY), width);
    col += debugInt(uv + vec2(-0.1 + offsetX*1.,offsetY), height);
    col += debugInt(uv + vec2(-0.1 + offsetX*2.,offsetY), depth);

    for (int i = 0; i < 25; i++) {
        offsetY += 0.05;
        col += debugInt(uv + vec2(-0.1 + offsetX*0.,offsetY), i);

        vec4 data1 = get_vec4(i);
        col += debugFloat(uv + vec2(-0.2 + offsetX*0.,offsetY), data1.x, 1);
        col += debugFloat(uv + vec2(-0.2 + offsetX*1.,offsetY), data1.y, 1);
        col += debugFloat(uv + vec2(-0.2 + offsetX*2.,offsetY), data1.z, 1);
        col += debugFloat(uv + vec2(-0.2 + offsetX*3.,offsetY), data1.w, 1);
    }

 #endif

    fragColor = vec4(col,1.);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = fragCoord/iResolution.xy;

    fragColor = vec4(0., 0., 0., 1.);
    displayData(fragColor, iResolution, fragCoord);
}
